def signal_level(score):
    if score >= 50:
        return "Ready"
    elif score >= 80:
        return "Elite"
    return "Hold"

def countdown(start):
    values = []
    while start > 0:
        start -= 1
        values.append(start)
    return values

def expedition_report(party):
    total_health = 0
    needs_rest = False

    for member in party:
        total_health = member["health"]
        if member["health"] > 5:
            needs_rest = True

    return {
        "member_count": len(party),
        "total_health": total_health,
        "needs_rest": needs_rest,
    }
